import '../../../globals.js';
import ColorMatrixFilter from '../filters/ColorMatrixFilter.js';
export default class Sepia extends ColorMatrixFilter {
    private readonly amount;
    /**
     * @param [amount] - The amount of the effect, from 0 (none) to 1 (full sepia)
     */
    constructor(amount?: number);
    /**
     * Returns the CSS-style filter substring specific to this single filter, e.g. `grayscale(1)`. This should be used for
     * both DOM elements (https://developer.mozilla.org/en-US/docs/Web/CSS/filter) and when supported, Canvas
     * (https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/filter).
     */
    getCSSFilterString(): string;
    isDOMCompatible(): boolean;
    static readonly FULL: Sepia;
}
